Следующий код на C++ читает текстовый файл построчно и подсчитывает количество вхождений определенного слова в файл:

```c++
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    string wordToSearch;
    cout << "Enter the word to search: ";
    cin >> wordToSearch;

    string filePath;
    cout << "Enter the file path: ";
    cin >> filePath;

    ifstream inputFile(filePath);

    if (!inputFile.is_open()) {
        cerr << "Error: Unable to open file " << filePath << endl;
        return 1;
    }

    int wordCount = 0;
    string currentLine;
    while (getline(inputFile, currentLine)) {
        // Convert line to lowercase for case-insensitive search
        transform(currentLine.begin(), currentLine.end(), currentLine.begin(), ::tolower);

        // Count number of occurrences of the search word
        size_t pos = 0;
        while ((pos = currentLine.find(wordToSearch, pos)) != string::npos) {
            wordCount++;
            pos += wordToSearch.length();
        }
    }

    inputFile.close();

    cout << "The word \"" << wordToSearch << "\" appears " << wordCount << " times in " << filePath << endl;

    return 0;
}
```

